const rawInput = $input.first()?.json || {};
let rawAgent2Json = rawInput.agent2_json ?? rawInput['Agent 2 JSON 结果'] ?? rawInput.data ?? '';

// 支持从 Markdown 报告中复制 ```json 包裹的 JSON。
function stripMarkdownFence(value) {
  const text = typeof value === 'string' ? value.trim() : value;
  if (typeof text !== 'string') {
    return text;
  }
  return text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function normalizeText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim().toLowerCase();
}

function looksLikeComplianceResult(item) {
  return !!item && typeof item === 'object' && (
    item.compliant_title !== undefined || item.original_title !== undefined || item.ready_for_agent3 !== undefined || item.safe_core_claim !== undefined
  );
}

function unwrapAgent2Payload(value) {
  if (Array.isArray(value)) {
    // Agent 2 V1.1 的真实输出通常是：[{ compliance_results: [...], approved_topics: [...] }]。
    const wrapper = value.find((item) => item && typeof item === 'object' && (Array.isArray(item.compliance_results) || Array.isArray(item.approved_topics)));
    if (wrapper) return wrapper;
    return { compliance_results: value.filter(looksLikeComplianceResult), approved_topics: [] };
  }
  if (value && typeof value === 'object') return value;
  return {};
}

function findByTitle(approvedTopics, complianceItem) {
  const possibleTitles = [
    complianceItem.original_title,
    complianceItem.compliant_title,
    complianceItem.title,
    complianceItem.topic,
  ].map(normalizeText).filter(Boolean);
  return approvedTopics.find((topic) => {
    const approvedTitles = [topic.title, topic.topic, topic.original_title, topic.compliant_title].map(normalizeText).filter(Boolean);
    return approvedTitles.some((title) => possibleTitles.includes(title));
  }) || {};
}

function mergeTopic(complianceItem, approvedItem, index) {
  const title = String(complianceItem.compliant_title ?? approvedItem.title ?? approvedItem.topic ?? complianceItem.original_title ?? '').trim();
  const topicName = String(approvedItem.topic ?? approvedItem.title ?? complianceItem.original_title ?? title).trim();
  const hook = String(complianceItem.compliant_hook ?? approvedItem.suggested_hook ?? complianceItem.original_hook ?? title).trim();
  return {
    ...approvedItem,
    ...complianceItem,
    topic: topicName || title,
    title: approvedItem.title ?? approvedItem.topic ?? complianceItem.original_title ?? title,
    ingredient: approvedItem.ingredient ?? complianceItem.ingredient,
    angle: approvedItem.angle ?? complianceItem.angle,
    target_audience: approvedItem.target_audience ?? complianceItem.target_audience,
    compliant_title: complianceItem.compliant_title ?? title,
    compliant_hook: complianceItem.compliant_hook ?? hook,
    safe_core_claim: complianceItem.safe_core_claim ?? 'General wellness education only. Not medical advice.',
    final_risk_level: complianceItem.final_risk_level ?? complianceItem.risk_level ?? approvedItem.risk_level,
    ready_for_agent3: complianceItem.ready_for_agent3,
    normalized_title: title,
    normalized_hook: hook,
    source_index: index + 1,
  };
}

try {
  let parsed = rawAgent2Json;
  if (typeof parsed === 'string') {
    parsed = JSON.parse(stripMarkdownFence(parsed));
  }

  const payload = unwrapAgent2Payload(parsed);
  const complianceResults = Array.isArray(payload.compliance_results)
    ? payload.compliance_results
    : (Array.isArray(payload.results) ? payload.results : []);
  const approvedTopics = Array.isArray(payload.approved_topics) ? payload.approved_topics : [];

  const topics = complianceResults
    .map((item, index) => mergeTopic(item, approvedTopics[index] || findByTitle(approvedTopics, item), index))
    .filter((topic) => topic.normalized_title);

  return [{
    json: {
      status: 'parsed',
      parse_error: '',
      source_agent: 'agent_2',
      topics,
      total_topics: topics.length,
    }
  }];
} catch (error) {
  return [{
    json: {
      status: 'error',
      parse_error: `Agent 2 JSON 解析失败：${error.message}`,
      source_agent: 'agent_2',
      topics: [],
      total_topics: 0,
    }
  }];
}

const data = $input.first()?.json || {};

if (data.status === 'error') {
  return [{
    json: {
      ...data,
      script_topics: [],
      selected_count: 0,
    }
  }];
}

function isReady(topic) {
  const value = topic.ready_for_agent3;
  return value === true || value === 1 || value === '1' || value === 'true' || value === 'True' || value === 'Yes' || value === 'yes';
}

const scriptTopics = (Array.isArray(data.topics) ? data.topics : [])
  .filter(isReady)
  .slice(0, 5);

return [{
  json: {
    ...data,
    status: scriptTopics.length > 0 ? 'ready_for_script' : 'insufficient_data',
    script_topics: scriptTopics,
    selected_count: scriptTopics.length,
    selection_note: scriptTopics.length > 0
      ? '已选择 ready_for_agent3 = true 的选题。'
      : '没有 ready_for_agent3 = true 的选题，Agent 3 不会生成脚本。',
  }
}];

const data = $input.first()?.json || {};

if (data.status === 'error' || data.status === 'insufficient_data') {
  return [{
    json: {
      ...data,
      draft_scripts: [],
    }
  }];
}

const riskyPhrases = ['cure', 'treat', 'prevent disease', 'replace medication'];

function cleanText(value) {
  let text = String(value || '').trim();
  for (const phrase of riskyPhrases) {
    const escaped = phrase.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\s+/g, '\\s+');
    text = text.replace(new RegExp(`\\b${escaped}\\b`, 'gi'), 'support general wellness');
  }
  return text;
}

function hashtagsFor(title) {
  const lower = title.toLowerCase();
  const tags = ['#WellnessTok', '#HealthyHabits', '#LearnOnTikTok'];
  if (lower.includes('tea')) tags.push('#TeaTok');
  if (lower.includes('rooibos')) tags.push('#Rooibos');
  if (lower.includes('ginger')) tags.push('#Ginger');
  if (lower.includes('routine')) tags.push('#DailyRoutine');
  return Array.from(new Set(tags)).slice(0, 6);
}

function scriptFor(topic, index) {
  const title = cleanText(topic.normalized_title || topic.compliant_title || topic.original_title);
  const hookSource = cleanText(topic.normalized_hook || topic.compliant_hook || title);
  const safeClaim = cleanText(topic.safe_core_claim || 'This is general wellness education, not medical advice.');
  const videoTitle = `${title} | Simple wellness story`;
  const hook = hookSource
    ? `If you've seen this wellness idea online, here is the safer way to understand it: ${hookSource}`
    : `This simple wellness idea is getting attention, but the wording matters.`;
  const body = [
    `Here is the idea: ${title}.`,
    `Instead of making big health promises, frame it as general wellness education.`,
    `${safeClaim}`,
    `For short-form content, keep the message simple: explain the habit, show the routine, and avoid disease or medication claims.`,
    `This keeps the video useful, clear, and safer for a US wellness audience.`
  ].join(' ');
  const cta = `Save this if you want more simple wellness ideas, and always check with a qualified professional for personal health questions.`;
  return {
    script_id: `agent3_script_${index + 1}`,
    source_title: topic.original_title || topic.normalized_title,
    video_title: videoTitle,
    video_description: `A short educational wellness video about ${title}. Not medical advice.`,
    video_goal: 'Turn an approved compliance-safe topic into a 30–45 second educational short video script.',
    estimated_duration: '30–45 seconds',
    hook,
    body,
    cta,
    hashtags: hashtagsFor(title),
    source_risk_level: topic.final_risk_level || topic.risk_level || 'unknown',
  };
}

const draftScripts = data.script_topics.map(scriptFor);

return [{
  json: {
    ...data,
    status: 'drafted',
    draft_scripts: draftScripts,
  }
}];

const data = $input.first()?.json || {};

if (data.status === 'error' || data.status === 'insufficient_data') {
  return [{
    json: {
      ...data,
      qa_scripts: [],
    }
  }];
}

const blockedPhrases = ['cure', 'treat', 'prevent disease', 'replace medication'];

function findBlocked(text) {
  const lower = String(text || '').toLowerCase();
  return blockedPhrases.filter((phrase) => lower.includes(phrase));
}

function safeRegeneratedHook(script) {
  return `This wellness topic is interesting, but let's keep the wording careful and educational.`;
}

function qaScript(script) {
  const hookIssues = findBlocked(script.hook);
  const bodyIssues = findBlocked(script.body);
  const ctaIssues = findBlocked(script.cta);
  const allIssues = Array.from(new Set([...hookIssues, ...bodyIssues, ...ctaIssues]));
  const hasHook = String(script.hook || '').trim().length >= 20;
  const hasCta = String(script.cta || '').trim().length >= 20;
  let fixedScript = { ...script };
  let regenerated = false;

  if (allIssues.length > 0) {
    fixedScript.hook = safeRegeneratedHook(script);
    fixedScript.body = String(script.body || '').replace(/cure|treat|prevent disease|replace medication/gi, 'support general wellness education');
    fixedScript.cta = `Save this for general wellness education, and talk to a qualified professional for personal health questions.`;
    regenerated = true;
  }

  return {
    ...fixedScript,
    qa: {
      hook_is_attractive: hasHook,
      cta_is_complete: hasCta,
      blocked_phrases_found: allIssues,
      regenerated_due_to_risk: regenerated,
      passed: allIssues.length === 0 && hasHook && hasCta,
    },
  };
}

const qaScripts = (data.draft_scripts || []).map(qaScript);

return [{
  json: {
    ...data,
    status: 'qa_complete',
    qa_scripts: qaScripts,
  }
}];

const data = $input.first()?.json || {};
const generatedAt = new Date().toISOString();
const scripts = Array.isArray(data.qa_scripts) ? data.qa_scripts : [];

function finalStatus() {
  if (data.status === 'error') return 'error';
  if (data.status === 'insufficient_data') return 'insufficient_data';
  return 'success';
}

function scriptMarkdown(script, index) {
  return [
    `## ${index + 1}. ${script.video_title}`,
    '',
    `**视频目标：** ${script.video_goal}`,
    '',
    `**预计时长：** ${script.estimated_duration}`,
    '',
    `**Hook（3 秒）：** ${script.hook}`,
    '',
    `**Body（约 30 秒）：** ${script.body}`,
    '',
    `**CTA（约 5 秒）：** ${script.cta}`,
    '',
    `**Hashtags：** ${script.hashtags.join(' ')}`,
    '',
    `**质量检查结果：** ${script.qa?.passed ? 'Passed' : 'Needs review'}；重新生成：${script.qa?.regenerated_due_to_risk ? 'Yes' : 'No'}；风险词：${(script.qa?.blocked_phrases_found || []).join(', ') || 'None'}`,
  ].join('\n');
}

const status = finalStatus();
const jsonResult = {
  workflow: 'AI Health OS',
  source_agent: 'agent_2',
  agent: 'agent_3',
  version: '1.1',
  status,
  scripts: status === 'success' ? scripts : [],
  handoff: {
    next_agent: 'agent_4',
    ready_count: status === 'success' ? scripts.length : 0,
  },
};

let reportMarkdown = '';
if (status === 'error') {
  reportMarkdown = [
    '# Agent 3 Script Report',
    '',
    '生成脚本数量：0',
    '',
    `错误：${data.parse_error || '未知错误'}`,
    '',
    '下一步：请重新粘贴 Agent 2 JSON。',
  ].join('\n');
} else if (status === 'insufficient_data') {
  reportMarkdown = [
    '# Agent 3 Script Report',
    '',
    '生成脚本数量：0',
    '',
    '没有 ready_for_agent3 = true 的选题，因此 Agent 3 没有生成脚本。',
    '',
    '下一步：请回到 Agent 2，确认至少一个选题 ready_for_agent3 = true。',
  ].join('\n');
} else {
  reportMarkdown = [
    '# Agent 3 Script Report',
    '',
    `生成脚本数量：${scripts.length}`,
    '',
    ...scripts.map(scriptMarkdown),
    '',
    '## 下一步',
    '',
    '交给 Agent 4。',
    '',
    '重要说明：Agent 3 只负责英文短视频脚本，不负责健康声明审核、医疗合规判断、图片、视频、配音或发布。',
  ].join('\n');
}

return [{
  json: {
    ...jsonResult,
    generated_at: generatedAt,
    report_markdown: reportMarkdown,
  }
}];
